CREATE TABLE IF NOT EXISTS page_records (
	id VARCHAR(36) NOT NULL, 
	chapter_id VARCHAR(36) NOT NULL, 
	page_number INTEGER NOT NULL, 
	original_path VARCHAR(512), 
	translated_path VARCHAR(512), 
	regions_json TEXT, 
	status VARCHAR(30), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(chapter_id) REFERENCES chapters (id) ON DELETE CASCADE
);
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('a87ef784-e154-4172-a299-1f28b581a181','9052de02-4583-4d85-9c1a-588ad6ec6a2b',1,'data/chapters/9052de02-4583-4d85-9c1a-588ad6ec6a2b/original/page_0001.jpg','data/chapters/9052de02-4583-4d85-9c1a-588ad6ec6a2b/translated/page_0001.png','[{"id": 1, "type": "sfx", "bbox": [55, 237, 137, 281], "source_text": "シュコ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 1, "is_vertical_text": true, "pixel_bbox": [65, 200, 164, 238]}, {"id": 2, "type": "sfx", "bbox": [10, 560, 102, 597], "source_text": "シュコ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 2, "is_vertical_text": true, "pixel_bbox": [11, 474, 122, 506]}, {"id": 3, "type": "dialogue", "bbox": [77, 575, 226, 736], "source_text": "I''VE SEEN TERRIBLE THINGS TODAY...", "speaker": "Miko", "gender": "female", "emotion": "neutral", "reading_order": 3, "is_vertical_text": false, "pixel_bbox": [92, 487, 270, 624], "translated_text": "Hari ini gue liat hal-hal parah banget..."}, {"id": 4, "type": "dialogue", "bbox": [211, 0, 355, 142], "source_text": "LOOKS LIKE I''LL BE HAVING NIGHTMARES", "speaker": "Miko", "gender": "female", "emotion": "neutral", "reading_order": 4, "is_vertical_text": false, "pixel_bbox": [252, 0, 425, 120], "translated_text": "Kayaknya bakal mimpi buruk nih gue"}, {"id": 5, "type": "sfx", "bbox": [390, 642, 492, 689], "source_text": "ブク", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 5, "is_vertical_text": true, "pixel_bbox": [467, 544, 589, 584]}, {"id": 6, "type": "sfx", "bbox": [390, 903, 498, 951], "source_text": "ブク", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 6, "is_vertical_text": true, "pixel_bbox": [467, 765, 597, 806]}, {"id": 7, "type": "dialogue", "bbox": [504, 883, 674, 982], "source_text": "I GUESS I''LL PUT SOME SALT IN MY ROOM AND GO TO SLEEP", "speaker": "Miko", "gender": "female", "emotion": "neutral", "reading_order": 7, "is_vertical_text": false, "pixel_bbox": [604, 748, 808, 832], "translated_text": "Mending gue tabur garam deh di kamar terus tidur"}, {"id": 8, "type": "sfx", "bbox": [759, 642, 856, 706], "source_text": "べぇ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 8, "is_vertical_text": true, "pixel_bbox": [910, 544, 1026, 598]}]','rendered','2026-10-10 10:47:22.991861');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('f3337b08-366b-4319-a729-eaa8cfae20fc','9052de02-4583-4d85-9c1a-588ad6ec6a2b',2,'data/chapters/9052de02-4583-4d85-9c1a-588ad6ec6a2b/original/page_0002.jpg','data/chapters/9052de02-4583-4d85-9c1a-588ad6ec6a2b/translated/page_0002.png','[{"id": 1, "type": "dialogue", "bbox": [773, 52, 878, 142], "source_text": "MY EYE HURTS... SOMETHING GOT IN", "speaker": "girl", "gender": "female", "emotion": "sad", "reading_order": 1, "is_vertical_text": false, "pixel_bbox": [926, 44, 1052, 120], "translated_text": "Duh mata gue sakit... kayaknya ada yang masuk"}, {"id": 2, "type": "dialogue", "bbox": [803, 442, 875, 497], "source_text": "OUCH...", "speaker": "girl", "gender": "female", "emotion": "sad", "reading_order": 2, "is_vertical_text": false, "pixel_bbox": [962, 374, 1049, 421], "translated_text": "Aduh..."}, {"id": 3, "type": "dialogue", "bbox": [802, 574, 856, 626], "source_text": "AH", "speaker": "girl", "gender": "female", "emotion": "shocked", "reading_order": 3, "is_vertical_text": false, "pixel_bbox": [961, 486, 1026, 530], "translated_text": "Ah"}, {"id": 4, "type": "dialogue", "bbox": [759, 874, 847, 915], "source_text": "...", "speaker": "girl", "gender": "female", "emotion": "neutral", "reading_order": 4, "is_vertical_text": false, "pixel_bbox": [910, 741, 1015, 775], "translated_text": "..."}]','rendered','2026-10-10 10:47:22.991861');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('69590c4b-7d61-4a94-a8ae-dee3d0cadc65','9052de02-4583-4d85-9c1a-588ad6ec6a2b',3,'data/chapters/9052de02-4583-4d85-9c1a-588ad6ec6a2b/original/page_0003.jpg','data/chapters/9052de02-4583-4d85-9c1a-588ad6ec6a2b/translated/page_0003.png','[{"id": 1, "type": "dialogue", "bbox": [43, 33, 137, 245], "source_text": "THERE''S NO WAY", "speaker": "female", "gender": "female", "emotion": "shocked", "reading_order": 1, "is_vertical_text": false, "pixel_bbox": [51, 28, 164, 208], "translated_text": "Nggak mungkin"}, {"id": 2, "type": "dialogue", "bbox": [45, 396, 179, 584], "source_text": "CRAP! CRAP! CRAP!", "speaker": "female", "gender": "female", "emotion": "shocked", "reading_order": 2, "is_vertical_text": false, "pixel_bbox": [54, 336, 214, 495], "translated_text": "Gawat! Gawat! Gawat!"}, {"id": 3, "type": "sfx", "bbox": [55, 663, 143, 765], "source_text": "パシャ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 3, "is_vertical_text": true, "pixel_bbox": [66, 562, 171, 649]}, {"id": 4, "type": "sfx", "bbox": [8, 874, 115, 966], "source_text": "ジャー", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 4, "is_vertical_text": true, "pixel_bbox": [9, 742, 138, 820]}, {"id": 5, "type": "sfx", "bbox": [257, 764, 353, 866], "source_text": "パシャ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 5, "is_vertical_text": true, "pixel_bbox": [308, 648, 423, 735]}, {"id": 6, "type": "dialogue", "bbox": [458, 20, 597, 227], "source_text": "IT SHOULD BE GONE THE NEXT TIME I LOOK LIKE THOSE HORROR FILMS", "speaker": "female", "gender": "female", "emotion": "neutral", "reading_order": 6, "is_vertical_text": false, "pixel_bbox": [549, 16, 716, 192], "translated_text": "Kayaknya bakal hilang pas gue liat lagi, kayak di film-film horor"}, {"id": 7, "type": "sfx", "bbox": [455, 274, 532, 381], "source_text": "バク", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 7, "is_vertical_text": true, "pixel_bbox": [546, 232, 638, 323]}, {"id": 8, "type": "dialogue", "bbox": [447, 400, 538, 538], "source_text": "CALM DOWN... IT''S OK...", "speaker": "female", "gender": "female", "emotion": "neutral", "reading_order": 8, "is_vertical_text": false, "pixel_bbox": [536, 339, 645, 456], "translated_text": "Tenang... nggak apa-apa..."}, {"id": 9, "type": "sfx", "bbox": [705, 87, 786, 175], "source_text": "バク", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 9, "is_vertical_text": true, "pixel_bbox": [846, 73, 943, 148]}, {"id": 10, "type": "sfx", "bbox": [712, 705, 804, 787], "source_text": "バク", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 10, "is_vertical_text": true, "pixel_bbox": [854, 598, 964, 668]}, {"id": 11, "type": "dialogue", "bbox": [458, 689, 552, 921], "source_text": "I MUST NOT REACT NO MATTER WHAT HANG IN THERE!", "speaker": "female", "gender": "female", "emotion": "neutral", "reading_order": 11, "is_vertical_text": false, "pixel_bbox": [549, 584, 662, 781], "translated_text": "Gue nggak boleh bereaksi bagaimanapun caranya, bertahanlah!"}, {"id": 12, "type": "sfx", "bbox": [880, 770, 966, 835], "source_text": "キュ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 12, "is_vertical_text": true, "pixel_bbox": [1056, 653, 1159, 708]}]','rendered','2026-10-10 10:47:22.991861');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('06ed9b85-6850-4256-a411-a060285928f2','9052de02-4583-4d85-9c1a-588ad6ec6a2b',4,'data/chapters/9052de02-4583-4d85-9c1a-588ad6ec6a2b/original/page_0004.jpg','data/chapters/9052de02-4583-4d85-9c1a-588ad6ec6a2b/translated/page_0004.png','[{"id": 1, "type": "other", "bbox": [735, 12, 746, 155], "source_text": "TL BY @ROKUUSO", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 1, "is_vertical_text": false, "pixel_bbox": [881, 10, 894, 131], "translated_text": "TERJEMAHAN OLEH @ROKUUSO"}, {"id": 2, "type": "narration", "bbox": [763, 62, 866, 266], "source_text": "IT''S NOT GOING AWAY.", "speaker": null, "gender": "narrator", "emotion": "neutral", "reading_order": 2, "is_vertical_text": false, "pixel_bbox": [914, 52, 1038, 225], "translated_text": "Nggak ilang-ilang."}, {"id": 3, "type": "dialogue", "bbox": [757, 650, 922, 786], "source_text": "IT''S STILL THERE", "speaker": "Girl", "gender": "female", "emotion": "sad", "reading_order": 3, "is_vertical_text": false, "pixel_bbox": [907, 551, 1105, 666], "translated_text": "Masih ada"}, {"id": 4, "type": "thought", "bbox": [883, 638, 977, 730], "source_text": "MY EYE STILL HURTS...", "speaker": "Girl", "gender": "female", "emotion": "sad", "reading_order": 4, "is_vertical_text": false, "pixel_bbox": [1058, 541, 1171, 619], "translated_text": "Mata gue masih sakit..."}]','rendered','2026-10-10 10:47:22.991861');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('bdf67abc-1d62-4cd0-8236-22ee933a8184','486b4b41-eba1-4d7f-859a-103c0272c69e',1,'data/chapters/486b4b41-eba1-4d7f-859a-103c0272c69e/original/page_0001.jpg','data/chapters/486b4b41-eba1-4d7f-859a-103c0272c69e/translated/page_0001.png','[{"id": 1, "type": "sfx", "bbox": [15, 26, 126, 620], "source_text": "ザァァァァ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 1, "is_vertical_text": false, "pixel_bbox": [18, 22, 151, 526]}, {"id": 2, "type": "dialogue", "bbox": [212, 574, 381, 680], "source_text": "IT''S POURING...", "speaker": "Girl", "gender": "female", "emotion": "neutral", "reading_order": 2, "is_vertical_text": false, "pixel_bbox": [254, 487, 457, 577], "translated_text": "Hujannya deres banget..."}, {"id": 3, "type": "dialogue", "bbox": [483, 31, 646, 153], "source_text": "I GOT PRETTY WET", "speaker": "Girl", "gender": "female", "emotion": "sad", "reading_order": 3, "is_vertical_text": false, "pixel_bbox": [579, 26, 775, 129], "translated_text": "Aku sampai basah kuyup."}, {"id": 4, "type": "dialogue", "bbox": [679, 29, 788, 154], "source_text": "EVEN MY SKIRT IS SOAKED.", "speaker": "Girl", "gender": "female", "emotion": "sad", "reading_order": 4, "is_vertical_text": false, "pixel_bbox": [814, 24, 945, 130], "translated_text": "Rokku juga basah semua."}]','rendered','2026-10-10 11:59:30.964335');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('6619ad26-d9bd-47d5-a9b9-67193f0e960e','486b4b41-eba1-4d7f-859a-103c0272c69e',2,'data/chapters/486b4b41-eba1-4d7f-859a-103c0272c69e/original/page_0002.jpg','data/chapters/486b4b41-eba1-4d7f-859a-103c0272c69e/translated/page_0002.png','[{"id": 1, "type": "dialogue", "bbox": [676, 114, 980, 269], "source_text": "CAN YOU SEE ME?", "speaker": "Ghost", "gender": "male", "emotion": "neutral", "reading_order": 1, "is_vertical_text": false, "pixel_bbox": [811, 96, 1176, 228], "translated_text": "Bisa lihat aku?"}]','rendered','2026-10-10 11:59:30.964335');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('0392a07d-1c26-47db-9e43-a45736f28ab1','486b4b41-eba1-4d7f-859a-103c0272c69e',3,'data/chapters/486b4b41-eba1-4d7f-859a-103c0272c69e/original/page_0003.jpg','data/chapters/486b4b41-eba1-4d7f-859a-103c0272c69e/translated/page_0003.png','[{"id": 1, "type": "dialogue", "bbox": [55, 33, 318, 142], "source_text": "CAN YOU SEE ME?", "speaker": "Monster", "gender": "male", "emotion": "neutral", "reading_order": 1, "is_vertical_text": true, "pixel_bbox": [66, 28, 381, 120], "translated_text": "Bisa lihat aku?"}, {"id": 2, "type": "dialogue", "bbox": [36, 381, 149, 447], "source_text": "HEY", "speaker": "Monster", "gender": "male", "emotion": "neutral", "reading_order": 2, "is_vertical_text": true, "pixel_bbox": [43, 323, 178, 379], "translated_text": "Woi"}, {"id": 3, "type": "dialogue", "bbox": [88, 689, 219, 755], "source_text": "...", "speaker": "Girl", "gender": "female", "emotion": "neutral", "reading_order": 3, "is_vertical_text": false, "pixel_bbox": [105, 584, 262, 640], "translated_text": "..."}, {"id": 4, "type": "sfx", "bbox": [481, 305, 533, 370], "source_text": "BEEP", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 4, "is_vertical_text": false, "pixel_bbox": [577, 258, 639, 314]}, {"id": 5, "type": "dialogue", "bbox": [435, 382, 608, 514], "source_text": "CAN\nAH, I\nHAVEN''T\nREPLIED\nTO MY\nLINE", "speaker": "Girl", "gender": "female", "emotion": "neutral", "reading_order": 5, "is_vertical_text": false, "pixel_bbox": [522, 324, 729, 436], "translated_text": "Bisa... Ah, aku belum balas LINE."}, {"id": 6, "type": "dialogue", "bbox": [629, 626, 856, 735], "source_text": "CAN YOU SEE ME", "speaker": "Monster", "gender": "male", "emotion": "neutral", "reading_order": 6, "is_vertical_text": true, "pixel_bbox": [754, 531, 1027, 624], "translated_text": "Bisa lihat aku?"}, {"id": 7, "type": "dialogue", "bbox": [757, 853, 915, 953], "source_text": "CAN\nYOU\nSEE\nME", "speaker": "Monster", "gender": "male", "emotion": "neutral", "reading_order": 7, "is_vertical_text": true, "pixel_bbox": [908, 724, 1098, 809], "translated_text": "BISA\nLIHAT\nAKU?"}]','rendered','2026-10-10 11:59:30.964335');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('8b6fa441-0f49-4481-b332-1dc32336b80a','486b4b41-eba1-4d7f-859a-103c0272c69e',4,'data/chapters/486b4b41-eba1-4d7f-859a-103c0272c69e/original/page_0004.jpg','data/chapters/486b4b41-eba1-4d7f-859a-103c0272c69e/translated/page_0004.png','[{"id": 1, "type": "sfx", "bbox": [10, 417, 73, 526], "source_text": "ズズ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 1, "is_vertical_text": false, "pixel_bbox": [12, 354, 87, 446]}, {"id": 2, "type": "sfx", "bbox": [12, 574, 76, 680], "source_text": "ズズ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 2, "is_vertical_text": false, "pixel_bbox": [14, 487, 91, 577]}, {"id": 3, "type": "dialogue", "bbox": [130, 420, 203, 502], "source_text": "CAN''T SEE IT", "speaker": "Miko", "gender": "female", "emotion": "shocked", "reading_order": 3, "is_vertical_text": false, "pixel_bbox": [156, 356, 243, 426], "translated_text": "Gak lihat."}, {"id": 4, "type": "dialogue", "bbox": [122, 715, 200, 807], "source_text": "CAN''T SEE IT", "speaker": "Miko", "gender": "female", "emotion": "shocked", "reading_order": 4, "is_vertical_text": false, "pixel_bbox": [146, 607, 240, 685], "translated_text": "Gak lihat."}, {"id": 5, "type": "dialogue", "bbox": [259, 13, 575, 269], "source_text": "I CAN REALLY SEE IT! I CAN REALLY SEE IT!!", "speaker": "Miko", "gender": "female", "emotion": "shocked", "reading_order": 5, "is_vertical_text": false, "pixel_bbox": [310, 11, 690, 228], "translated_text": "Aku beneran bisa lihat! Aku beneran bisa lihat!!"}, {"id": 6, "type": "sfx", "bbox": [251, 313, 584, 421], "source_text": "バババ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 6, "is_vertical_text": true, "pixel_bbox": [301, 265, 700, 357]}, {"id": 7, "type": "sfx", "bbox": [250, 650, 584, 755], "source_text": "ババ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 7, "is_vertical_text": true, "pixel_bbox": [300, 551, 700, 640]}, {"id": 8, "type": "dialogue", "bbox": [260, 825, 638, 974], "source_text": "I''M CONFUSED WHAT THE HECK WAS THAT", "speaker": "Miko", "gender": "female", "emotion": "shocked", "reading_order": 8, "is_vertical_text": false, "pixel_bbox": [312, 700, 765, 826], "translated_text": "Aku bingung, itu apaan sih?"}, {"id": 9, "type": "sfx", "bbox": [672, 281, 804, 385], "source_text": "キュッ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 9, "is_vertical_text": true, "pixel_bbox": [806, 238, 964, 326]}, {"id": 10, "type": "narration", "bbox": [734, 31, 983, 246], "source_text": "I CAN REALLY SEE IT.", "speaker": "Miko", "gender": "female", "emotion": "neutral", "reading_order": 10, "is_vertical_text": false, "pixel_bbox": [880, 26, 1179, 208], "translated_text": "Aku beneran bisa lihat."}, {"id": 11, "type": "sfx", "bbox": [811, 252, 977, 345], "source_text": "ガタ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 11, "is_vertical_text": true, "pixel_bbox": [973, 213, 1172, 292]}, {"id": 12, "type": "sfx", "bbox": [811, 672, 975, 768], "source_text": "ガタガタ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 12, "is_vertical_text": true, "pixel_bbox": [973, 570, 1170, 652]}, {"id": 13, "type": "sfx", "bbox": [674, 856, 977, 965], "source_text": "バ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 13, "is_vertical_text": true, "pixel_bbox": [808, 726, 1172, 819]}, {"id": 14, "type": "other", "bbox": [984, 878, 999, 997], "source_text": "TL BY @SN2B", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 14, "is_vertical_text": false, "pixel_bbox": [1180, 745, 1198, 846], "translated_text": "TL oleh @SN2B"}]','rendered','2026-10-10 11:59:30.964335');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('743ad0e0-26f9-414e-a038-04416068ea88','349d06d9-3d73-403a-8be1-2f6a62c6a9e6',1,'data/chapters/349d06d9-3d73-403a-8be1-2f6a62c6a9e6/original/page_0001.jpg','data/chapters/349d06d9-3d73-403a-8be1-2f6a62c6a9e6/translated/page_0001.png','[{"id": 1, "type": "narration", "bbox": [10, 843, 116, 995], "source_text": "RECAP\nRECENTLY, I''VE BEEN STARTING TO SEE THINGS.", "speaker": null, "gender": "narrator", "emotion": "neutral", "reading_order": 1, "is_vertical_text": false, "pixel_bbox": [12, 714, 139, 843], "translated_text": "REKAP\nBELAKANGAN INI, GUE MULAI MELIHAT HAL-HAL ANEH."}, {"id": 2, "type": "sfx", "bbox": [22, 545, 143, 614], "source_text": "ゴト", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 2, "is_vertical_text": true, "pixel_bbox": [26, 462, 171, 520]}, {"id": 3, "type": "sfx", "bbox": [203, 539, 275, 592], "source_text": "サラサラ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 3, "is_vertical_text": true, "pixel_bbox": [243, 457, 330, 502]}, {"id": 4, "type": "dialogue", "bbox": [179, 13, 319, 203], "source_text": "THE SALT IS READY...", "speaker": "Miko", "gender": "female", "emotion": "neutral", "reading_order": 4, "is_vertical_text": false, "pixel_bbox": [214, 11, 382, 172], "translated_text": "Garamnya udah siap..."}, {"id": 5, "type": "sfx", "bbox": [390, 168, 452, 222], "source_text": "ポッ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 5, "is_vertical_text": true, "pixel_bbox": [468, 142, 542, 188]}, {"id": 6, "type": "dialogue", "bbox": [390, 260, 461, 335], "source_text": "SIGH", "speaker": "Miko", "gender": "female", "emotion": "sad", "reading_order": 6, "is_vertical_text": false, "pixel_bbox": [468, 220, 553, 284], "translated_text": "Haaah..."}, {"id": 7, "type": "dialogue", "bbox": [435, 436, 686, 672], "source_text": "THEY SHOULD DISAPPEAR IF I JUST IGNORE THEM. I''LL BE FINE.", "speaker": "Miko", "gender": "female", "emotion": "neutral", "reading_order": 7, "is_vertical_text": false, "pixel_bbox": [522, 369, 823, 569], "translated_text": "Kalau gue cuekin, mereka pasti ilang sendiri. Gue pasti bakal baik-baik aja."}, {"id": 8, "type": "dialogue", "bbox": [492, 856, 765, 995], "source_text": "EVEN IF I SEE THEM AGAIN", "speaker": "Miko", "gender": "female", "emotion": "neutral", "reading_order": 8, "is_vertical_text": false, "pixel_bbox": [590, 725, 918, 843], "translated_text": "Sekalipun gue liat mereka lagi..."}, {"id": 9, "type": "sfx", "bbox": [884, 94, 951, 143], "source_text": "タタ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 9, "is_vertical_text": true, "pixel_bbox": [1060, 79, 1141, 121]}, {"id": 10, "type": "sfx", "bbox": [884, 381, 955, 432], "source_text": "タン", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 10, "is_vertical_text": true, "pixel_bbox": [1060, 323, 1146, 366]}, {"id": 11, "type": "narration", "bbox": [883, 447, 989, 574], "source_text": "IN THE BATHROOM FOR ABOUT 20 MINS.", "speaker": null, "gender": "narrator", "emotion": "neutral", "reading_order": 11, "is_vertical_text": false, "pixel_bbox": [1059, 379, 1186, 486], "translated_text": "Udah 20 menit di kamar mandi."}]','rendered','2026-10-10 12:20:56.394626');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('199cd407-b082-4a8e-9b5e-319be370896e','349d06d9-3d73-403a-8be1-2f6a62c6a9e6',2,'data/chapters/349d06d9-3d73-403a-8be1-2f6a62c6a9e6/original/page_0002.jpg','data/chapters/349d06d9-3d73-403a-8be1-2f6a62c6a9e6/translated/page_0002.png','[{"id": 1, "type": "sfx", "bbox": [58, 674, 169, 725], "source_text": "ト", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 1, "is_vertical_text": true, "pixel_bbox": [69, 571, 202, 614]}, {"id": 2, "type": "sfx", "bbox": [151, 163, 237, 214], "source_text": "月", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 2, "is_vertical_text": true, "pixel_bbox": [181, 138, 284, 181]}, {"id": 3, "type": "other", "bbox": [71, 740, 319, 977], "source_text": "Ganglo\nexorcism\nexorcism\nexorcism good", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 3, "is_vertical_text": false, "pixel_bbox": [85, 627, 382, 828], "translated_text": "Ganglo\nngusir hantu\nngusir hantu\nngusir hantu manjur"}, {"id": 4, "type": "thought", "bbox": [243, 102, 355, 171], "source_text": "...", "speaker": "girl", "gender": "female", "emotion": "neutral", "reading_order": 4, "is_vertical_text": false, "pixel_bbox": [291, 86, 426, 145], "translated_text": "..."}, {"id": 5, "type": "dialogue", "bbox": [435, 36, 497, 142], "source_text": "PRAYER BEADS...", "speaker": "girl", "gender": "female", "emotion": "neutral", "reading_order": 5, "is_vertical_text": false, "pixel_bbox": [522, 30, 596, 120], "translated_text": "Tasbih..."}, {"id": 6, "type": "sfx", "bbox": [545, 786, 626, 976], "source_text": "オオオ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 6, "is_vertical_text": false, "pixel_bbox": [654, 666, 751, 827]}, {"id": 7, "type": "sfx", "bbox": [676, 38, 775, 169], "source_text": "ギシ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 7, "is_vertical_text": false, "pixel_bbox": [811, 32, 930, 143]}, {"id": 8, "type": "dialogue", "bbox": [705, 532, 856, 686], "source_text": "I SHOULD GO TO SLEEP.", "speaker": "girl", "gender": "female", "emotion": "neutral", "reading_order": 8, "is_vertical_text": false, "pixel_bbox": [846, 451, 1027, 581], "translated_text": "Mending gue tidur aja lah."}, {"id": 9, "type": "thought", "bbox": [702, 715, 762, 782], "source_text": "SIGH", "speaker": "girl", "gender": "female", "emotion": "neutral", "reading_order": 9, "is_vertical_text": false, "pixel_bbox": [842, 606, 914, 663], "translated_text": "Haaah..."}, {"id": 10, "type": "sfx", "bbox": [673, 874, 735, 963], "source_text": "ポス", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 10, "is_vertical_text": false, "pixel_bbox": [807, 741, 882, 816]}]','rendered','2026-10-10 12:20:56.394626');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('31713f08-81c2-47a2-a4da-764250a60eef','349d06d9-3d73-403a-8be1-2f6a62c6a9e6',3,'data/chapters/349d06d9-3d73-403a-8be1-2f6a62c6a9e6/original/page_0003.jpg','data/chapters/349d06d9-3d73-403a-8be1-2f6a62c6a9e6/translated/page_0003.png','[{"id": 1, "type": "dialogue", "bbox": [705, 115, 878, 240], "source_text": "MAMA...", "speaker": "unknown", "gender": "unknown", "emotion": "shocked", "reading_order": 1, "is_vertical_text": false, "pixel_bbox": [846, 97, 1053, 203], "translated_text": "Mama..."}]','rendered','2026-10-10 12:20:56.394626');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('2909502f-527d-45e1-b8e5-3d64c17e1feb','349d06d9-3d73-403a-8be1-2f6a62c6a9e6',4,'data/chapters/349d06d9-3d73-403a-8be1-2f6a62c6a9e6/original/page_0004.jpg','data/chapters/349d06d9-3d73-403a-8be1-2f6a62c6a9e6/translated/page_0004.png','[{"id": 1, "type": "sfx", "bbox": [23, 342, 64, 392], "source_text": "pop", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 1, "is_vertical_text": false, "pixel_bbox": [27, 290, 76, 332]}, {"id": 2, "type": "dialogue", "bbox": [113, 25, 304, 96], "source_text": "MA... MA", "speaker": "Girl", "gender": "female", "emotion": "sad", "reading_order": 2, "is_vertical_text": true, "pixel_bbox": [135, 21, 364, 81], "translated_text": "Ma... ma..."}, {"id": 3, "type": "sfx", "bbox": [471, 18, 561, 119], "source_text": "gyu", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 3, "is_vertical_text": false, "pixel_bbox": [565, 15, 673, 100]}, {"id": 4, "type": "narration", "bbox": [700, 51, 954, 228], "source_text": "THE SALT DIDN''T WORK AFTER ALL.", "speaker": null, "gender": "narrator", "emotion": "neutral", "reading_order": 4, "is_vertical_text": false, "pixel_bbox": [840, 43, 1144, 193], "translated_text": "Ternyata garamnya nggak mempan."}, {"id": 5, "type": "thought", "bbox": [786, 715, 945, 964], "source_text": "GUESS I''LL HAVE TO GET SOME PRAYER BEADS TOMORROW...", "speaker": "Girl", "gender": "female", "emotion": "neutral", "reading_order": 5, "is_vertical_text": false, "pixel_bbox": [943, 606, 1134, 817], "translated_text": "Kayaknya besok gue harus cari tasbih deh..."}, {"id": 6, "type": "thought", "bbox": [820, 677, 878, 753], "source_text": "GOTTA WASH MY SHEETS LATER", "speaker": "Girl", "gender": "female", "emotion": "neutral", "reading_order": 6, "is_vertical_text": false, "pixel_bbox": [983, 574, 1053, 638], "translated_text": "Nanti harus cuci sprei nih."}, {"id": 7, "type": "sign", "bbox": [970, 790, 994, 996], "source_text": "TL BY @ROKUUSO", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 7, "is_vertical_text": false, "pixel_bbox": [1164, 669, 1192, 844]}]','rendered','2026-10-10 12:20:56.394626');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('6165a660-86da-4be1-bbef-cb3615794d64','82801f43-4d5e-4a81-9001-17fd997b67bb',1,'data/chapters/82801f43-4d5e-4a81-9001-17fd997b67bb/original/page_0001.jpg','data/chapters/82801f43-4d5e-4a81-9001-17fd997b67bb/translated/page_0001.png','[{"id": 1, "type": "narration", "bbox": [43, 853, 91, 989], "source_text": "RECAP", "speaker": null, "gender": "narrator", "emotion": "neutral", "reading_order": 1, "is_vertical_text": false, "pixel_bbox": [51, 723, 109, 838], "translated_text": "REKAP"}, {"id": 2, "type": "dialogue", "bbox": [55, 23, 196, 137], "source_text": "...AND SO, I WAS IN A RUSH... THAT''S HOW I FORGOT MY PANTIES.", "speaker": "Yuria", "gender": "female", "emotion": "neutral", "reading_order": 2, "is_vertical_text": false, "pixel_bbox": [66, 19, 235, 116], "translated_text": "...JADI GITU, GUE LAGI BURU-BURU... MAKANYA GUE LUPA PAKE CD."}, {"id": 3, "type": "sfx", "bbox": [10, 755, 151, 811], "source_text": "HELP", "speaker": null, "gender": "unknown", "emotion": "shocked", "reading_order": 3, "is_vertical_text": true, "pixel_bbox": [12, 640, 181, 687]}, {"id": 4, "type": "sfx", "bbox": [168, 770, 252, 825], "source_text": "HELP", "speaker": null, "gender": "unknown", "emotion": "shocked", "reading_order": 4, "is_vertical_text": true, "pixel_bbox": [201, 652, 302, 699]}, {"id": 5, "type": "narration", "bbox": [128, 836, 269, 978], "source_text": "RECENTLY, I''VE BEEN STARTING TO SEE THINGS.", "speaker": "Miko", "gender": "female", "emotion": "neutral", "reading_order": 5, "is_vertical_text": false, "pixel_bbox": [153, 708, 322, 829], "translated_text": "AKHIR-AKHIR INI, GUE MULAI MELIHAT HAL-HAL ANEH."}, {"id": 6, "type": "dialogue", "bbox": [453, 386, 517, 542], "source_text": "WHY PRAYER BEADS?", "speaker": "Miko", "gender": "female", "emotion": "neutral", "reading_order": 6, "is_vertical_text": false, "pixel_bbox": [543, 327, 620, 459], "translated_text": "Kenapa harus tasbih?"}, {"id": 7, "type": "dialogue", "bbox": [415, 6, 563, 147], "source_text": "AH! I THOUGHT IT MIGHT LOOK STYLISH.", "speaker": "Yuria", "gender": "female", "emotion": "neutral", "reading_order": 7, "is_vertical_text": false, "pixel_bbox": [498, 5, 675, 124], "translated_text": "AH! Gue pikir bakal kelihatan stylish gitu."}, {"id": 8, "type": "sfx", "bbox": [374, 804, 477, 853], "source_text": "スル", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 8, "is_vertical_text": true, "pixel_bbox": [448, 681, 572, 723]}, {"id": 9, "type": "dialogue", "bbox": [603, 196, 680, 273], "source_text": "AH!", "speaker": "Yuria", "gender": "female", "emotion": "neutral", "reading_order": 9, "is_vertical_text": false, "pixel_bbox": [723, 166, 816, 231], "translated_text": "AH!"}, {"id": 10, "type": "sfx", "bbox": [732, 175, 786, 222], "source_text": "そわ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 10, "is_vertical_text": true, "pixel_bbox": [878, 148, 943, 188]}, {"id": 11, "type": "sfx", "bbox": [727, 442, 784, 489], "source_text": "はあ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 11, "is_vertical_text": true, "pixel_bbox": [872, 374, 940, 414]}, {"id": 12, "type": "sfx", "bbox": [804, 381, 866, 427], "source_text": "そわ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 12, "is_vertical_text": true, "pixel_bbox": [964, 323, 1039, 362]}, {"id": 13, "type": "dialogue", "bbox": [705, 555, 788, 629], "source_text": "PRAY- ER BEADS?", "speaker": "Yuria", "gender": "female", "emotion": "neutral", "reading_order": 13, "is_vertical_text": false, "pixel_bbox": [846, 470, 945, 533], "translated_text": "TAS- BIH?"}, {"id": 14, "type": "dialogue", "bbox": [791, 552, 893, 649], "source_text": "HMM, MAYBE DONKI?*", "speaker": "Yuria", "gender": "female", "emotion": "neutral", "reading_order": 14, "is_vertical_text": false, "pixel_bbox": [949, 468, 1071, 550], "translated_text": "Hmm, mungkin di Donki?"}, {"id": 15, "type": "dialogue", "bbox": [707, 836, 808, 912], "source_text": "UMM, HANA", "speaker": "Miko", "gender": "female", "emotion": "neutral", "reading_order": 15, "is_vertical_text": false, "pixel_bbox": [848, 708, 969, 773], "translated_text": "Um, Hana"}, {"id": 16, "type": "dialogue", "bbox": [833, 835, 995, 993], "source_text": "DO YOU KNOW ANY PLACE THAT SELLS PRAYER BEADS?", "speaker": "Miko", "gender": "female", "emotion": "neutral", "reading_order": 16, "is_vertical_text": false, "pixel_bbox": [999, 708, 1194, 842], "translated_text": "Kamu tahu tempat yang jual tasbih nggak?"}, {"id": 17, "type": "other", "bbox": [986, 560, 996, 847], "source_text": "*DONKI IS A POPULAR DISCOUNT CHAIN STORE IN JAPAN", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 17, "is_vertical_text": false, "pixel_bbox": [1183, 474, 1195, 718], "translated_text": "*Donki adalah jaringan toko diskon populer di Jepang"}]','rendered','2026-10-10 12:50:05.072839');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('d98ceada-5ec4-469c-9246-4375b5f5928d','82801f43-4d5e-4a81-9001-17fd997b67bb',2,'data/chapters/82801f43-4d5e-4a81-9001-17fd997b67bb/original/page_0002.jpg','data/chapters/82801f43-4d5e-4a81-9001-17fd997b67bb/translated/page_0002.png','[{"id": 1, "type": "dialogue", "bbox": [55, 95, 235, 203], "source_text": "A STRAY CAT?", "speaker": "unknown", "gender": "female", "emotion": "neutral", "reading_order": 1, "is_vertical_text": false, "pixel_bbox": [66, 80, 282, 172], "translated_text": "Kucing liar?"}, {"id": 2, "type": "sfx", "bbox": [33, 381, 115, 439], "source_text": "みゃあ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 2, "is_vertical_text": true, "pixel_bbox": [39, 323, 138, 372]}, {"id": 3, "type": "sfx", "bbox": [43, 529, 131, 584], "source_text": "みゃあ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 3, "is_vertical_text": true, "pixel_bbox": [51, 448, 157, 495]}, {"id": 4, "type": "sign", "bbox": [211, 401, 239, 532], "source_text": "Amasan", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 4, "is_vertical_text": false, "pixel_bbox": [253, 340, 286, 451], "translated_text": "Amasan"}, {"id": 5, "type": "dialogue", "bbox": [67, 814, 234, 956], "source_text": "LOOK...", "speaker": "unknown", "gender": "female", "emotion": "neutral", "reading_order": 5, "is_vertical_text": false, "pixel_bbox": [80, 690, 280, 810], "translated_text": "Lihat deh..."}, {"id": 6, "type": "dialogue", "bbox": [304, 433, 477, 563], "source_text": "What''s wrong, kitty?", "speaker": "Dark-haired girl", "gender": "female", "emotion": "neutral", "reading_order": 6, "is_vertical_text": false, "pixel_bbox": [364, 367, 572, 477], "translated_text": "Kenapa, kucing kecil?"}, {"id": 7, "type": "dialogue", "bbox": [262, 608, 513, 755], "source_text": "LOOK AT THAT! IT''S SO TINY!", "speaker": "Light-haired girl", "gender": "female", "emotion": "shocked", "reading_order": 7, "is_vertical_text": false, "pixel_bbox": [314, 515, 615, 640], "translated_text": "LIHAT ITU! KECIL BANGET!"}, {"id": 8, "type": "dialogue", "bbox": [264, 826, 525, 953], "source_text": "WAAAHH! SO CUTEEE!", "speaker": "Light-haired girl", "gender": "female", "emotion": "shocked", "reading_order": 8, "is_vertical_text": false, "pixel_bbox": [316, 700, 630, 808], "translated_text": "WAAAHH! LUCU BANGET!"}, {"id": 9, "type": "dialogue", "bbox": [607, 584, 735, 664], "source_text": "...", "speaker": "unknown", "gender": "female", "emotion": "neutral", "reading_order": 9, "is_vertical_text": false, "pixel_bbox": [728, 495, 882, 563], "translated_text": "..."}, {"id": 10, "type": "sfx", "bbox": [712, 638, 792, 706], "source_text": "みゃあ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 10, "is_vertical_text": true, "pixel_bbox": [854, 541, 950, 598]}, {"id": 11, "type": "dialogue", "bbox": [672, 396, 831, 535], "source_text": "I''VE BEEN SEEING NOTHING BUT TERRIBLE THINGS LATELY.", "speaker": "Light-haired girl", "gender": "female", "emotion": "sad", "reading_order": 11, "is_vertical_text": false, "pixel_bbox": [806, 335, 997, 453], "translated_text": "Belakangan ini gue cuma lihat hal-hal yang parah banget."}, {"id": 12, "type": "dialogue", "bbox": [650, 0, 999, 149], "source_text": "I NEED SOME COMFORT TOO.", "speaker": "Dark-haired girl", "gender": "female", "emotion": "neutral", "reading_order": 12, "is_vertical_text": false, "pixel_bbox": [780, 0, 1198, 126], "translated_text": "Gue juga butuh hiburan."}]','rendered','2026-10-10 12:50:05.072839');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('0cc3aacb-9090-411e-befd-62a8a46a6197','82801f43-4d5e-4a81-9001-17fd997b67bb',3,'data/chapters/82801f43-4d5e-4a81-9001-17fd997b67bb/original/page_0003.jpg','data/chapters/82801f43-4d5e-4a81-9001-17fd997b67bb/translated/page_0003.png','[{"id": 1, "type": "sfx", "bbox": [555, 120, 645, 175], "source_text": "ペロ", "speaker": "kitten", "gender": "unknown", "emotion": "neutral", "reading_order": 1, "is_vertical_text": true, "pixel_bbox": [666, 101, 774, 148]}, {"id": 2, "type": "sfx", "bbox": [602, 307, 722, 375], "source_text": "ペロ", "speaker": "kitten", "gender": "unknown", "emotion": "neutral", "reading_order": 2, "is_vertical_text": true, "pixel_bbox": [722, 260, 866, 318]}, {"id": 3, "type": "dialogue", "bbox": [763, 14, 882, 137], "source_text": "AWFUL INDEED.", "speaker": "black-haired girl", "gender": "female", "emotion": "neutral", "reading_order": 3, "is_vertical_text": false, "pixel_bbox": [915, 11, 1058, 116], "translated_text": "Parah banget emang."}, {"id": 4, "type": "sfx", "bbox": [734, 765, 874, 829], "source_text": "キュン♡", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 4, "is_vertical_text": true, "pixel_bbox": [880, 648, 1048, 702]}, {"id": 5, "type": "dialogue", "bbox": [712, 856, 992, 977], "source_text": "IT''S LICKING MY FINGER♡ ISN''T THIS AWFUL~?", "speaker": "pink-haired girl", "gender": "female", "emotion": "neutral", "reading_order": 5, "is_vertical_text": false, "pixel_bbox": [854, 725, 1190, 828], "translated_text": "Dia lagi jilat jari gue♡ Lucu banget ya~?"}]','rendered','2026-10-10 12:50:05.072839');
INSERT OR REPLACE INTO "page_records" (id, chapter_id, page_number, original_path, translated_path, regions_json, status, created_at) VALUES('5aa09bcf-7e2a-4ed3-9092-e4c4b0445e70','82801f43-4d5e-4a81-9001-17fd997b67bb',4,'data/chapters/82801f43-4d5e-4a81-9001-17fd997b67bb/original/page_0004.jpg','data/chapters/82801f43-4d5e-4a81-9001-17fd997b67bb/translated/page_0004.png','[{"id": 1, "type": "sfx", "bbox": [29, 363, 115, 439], "source_text": "ズ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 1, "is_vertical_text": true, "pixel_bbox": [34, 307, 138, 372]}, {"id": 2, "type": "sfx", "bbox": [151, 411, 230, 485], "source_text": "ズズ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 2, "is_vertical_text": true, "pixel_bbox": [181, 348, 276, 411]}, {"id": 3, "type": "dialogue", "bbox": [43, 502, 179, 616], "source_text": "I GUESS I COULD RAISE IT MYSELF.", "speaker": "Girl", "gender": "female", "emotion": "neutral", "reading_order": 3, "is_vertical_text": false, "pixel_bbox": [51, 425, 214, 522], "translated_text": "Kayaknya gue pelihara sendiri aja deh."}, {"id": 4, "type": "sfx", "bbox": [39, 663, 126, 755], "source_text": "ひょいっ", "speaker": null, "gender": "unknown", "emotion": "neutral", "reading_order": 4, "is_vertical_text": true, "pixel_bbox": [46, 562, 151, 640]}, {"id": 5, "type": "dialogue", "bbox": [27, 825, 142, 988], "source_text": "WHAT A TERRIBLE THING TO DO, ABANDONING A CAT.", "speaker": "Girl", "gender": "female", "emotion": "neutral", "reading_order": 5, "is_vertical_text": false, "pixel_bbox": [32, 699, 170, 837], "translated_text": "Tega banget ya, buang kucing kayak gini."}, {"id": 6, "type": "dialogue", "bbox": [426, 21, 521, 525], "source_text": "AWFUL. AWFUL.", "speaker": "Unknown", "gender": "unknown", "emotion": "angry", "reading_order": 6, "is_vertical_text": false, "pixel_bbox": [511, 17, 625, 445], "translated_text": "Parah. Parah banget."}, {"id": 7, "type": "dialogue", "bbox": [712, 21, 807, 187], "source_text": "WHAT DO YOU THINK?", "speaker": "Girl", "gender": "female", "emotion": "neutral", "reading_order": 7, "is_vertical_text": false, "pixel_bbox": [854, 17, 968, 158], "translated_text": "Menurut kamu gimana?"}, {"id": 8, "type": "narration", "bbox": [807, 27, 987, 197], "source_text": "AWFUL.", "speaker": null, "gender": "narrator", "emotion": "neutral", "reading_order": 8, "is_vertical_text": false, "pixel_bbox": [968, 22, 1184, 167], "translated_text": "PARAH."}]','rendered','2026-10-10 12:50:05.072839');
COMMIT;
